  checkMarkers(prevT,S.t);
  apply();
  if(S.playing)S.raf=requestAnimationFrame(tick);
}
function startLoop(){
  if(!S.playing){S.playing=true;S.last=performance.now();S.raf=requestAnimationFrame(tick);}
}
function checkMarkers(a,b){
  if(!DATA.markerTriggers.length)return;
  var m,tr,j;
  for(j=0;j<DATA.markerTriggers.length;j++){
    tr=DATA.markerTriggers[j];
    m=tr.time;
    if((a<m&&b>=m)||(S.speed<0&&a>m&&b<=m))runAction(tr);
  }
}

/* ---------- actions ---------- */
function findSeg(idOrName){
  for(var j=0;j<DATA.segments.length;j++){
    if(DATA.segments[j].id===idOrName||DATA.segments[j].name===idOrName)return DATA.segments[j];
  }
